package com.tecsup;
import java.util.*; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid;
@RestController @RequestMapping("/api/categorias") public class CategoriaController { private final CategoriaRepository repo; public CategoriaController(CategoriaRepository r){repo=r;} @GetMapping public List<Categoria> all(){return repo.findAll();} @GetMapping("/{id}") public Categoria one(@PathVariable Long id){return repo.findById(id).orElseThrow();} @PostMapping public Categoria create(@Valid @RequestBody Categoria c){c.id=null;return repo.save(c);} @PutMapping("/{id}") public Categoria update(@PathVariable Long id,@Valid @RequestBody Categoria c){c.id=id;return repo.save(c);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);} }
